WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_m_travel'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '工程与行程', 'kp-eng-m-travel', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "工程与行程同构"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "工程问题和行程问题在数学模型上完全等价。可以互相转化思维。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心同构模型"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "工作总量 (W) = 路程 (S)"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "工作效率 (P) = 速度 (V)"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "工作时间 (T) = 时间 (T)"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、实战妙用"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到难懂的工程题，把它翻译成两个人跑步；遇到复杂的行程题，把它翻译成两个人干活。"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "甲乙合作完工 = 两人相向而行相遇。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "甲效率比乙高，甲干完一部分乙才开始 = 两人同向跑的追及问题。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "水管进水与漏水 = 顺水行船与逆水行船（船速与水速）。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[遇到抽象的进水漏水或两队合作题] --> B[在脑子里把它们翻译成两辆车在公路上跑]\nB --> C[利用行程问题中极其直观的'线段图'来标示进度]\nC --> D[写出行程公式 S=VT]\nD --> E[再把S和V翻译回工程的总量和效率, 解题完成]"}}]}$$ AS jsonb), NULL, '工程与行程的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "工程与行程"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_m_travel", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
